PRAGMA foreign_keys=ON;CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,source TEXT NOT NULL,source_listing_id TEXT,listing_url TEXT,address TEXT,city TEXT,county TEXT,lat REAL NOT NULL,lon REAL NOT NULL,acres REAL,price REAL,image_source_url TEXT,image_index INTEGER,image_phash TEXT,image_storage_allowed INTEGER DEFAULT 0,archived_image_path TEXT,detected_confidence REAL NOT NULL,deer_count INTEGER DEFAULT 1,sex_classification TEXT,antler_notes TEXT,observed_at TEXT,confirmed_at TEXT NOT NULL,confirmed INTEGER NOT NULL DEFAULT 1,deer_id TEXT,reid_confidence REAL,nearest_public_land TEXT,harvest_status TEXT DEFAULT 'unknown',harvest_date TEXT,harvest_evidence_note TEXT,UNIQUE(source,source_listing_id,image_phash));CREATE TABLE IF NOT EXISTS deer_profiles(deer_id TEXT PRIMARY KEY,nickname TEXT,sex TEXT,area_label TEXT,first_seen TEXT,last_seen TEXT,sighting_count INTEGER DEFAULT 0,identity_confidence REAL,antler_signature TEXT,phenotype_notes TEXT,lineage_notes TEXT,genetics_evidence_type TEXT DEFAULT 'visual_phenotype_only',harvest_status TEXT DEFAULT 'unknown',harvest_date TEXT,harvest_evidence_note TEXT,harvest_verified_by TEXT);CREATE TABLE IF NOT EXISTS deer_embeddings(observation_id TEXT PRIMARY KEY,deer_id TEXT,embedding_json TEXT NOT NULL);